          "analysis": "<strong>🎯 答案解析：</strong>选\"学校教育、家庭教育、社会教育\"。\"三结合教育\"是指学校、家庭、社会三种教育力量相互配合，形成教育合力。<br><br><strong>📚 知识点讲解：</strong>\"三结合教育\"是现代教育学中的重要概念，强调学校教育、家庭教育、社会教育三者的协调配合。学校教育起主导作用，家庭教育是基础，社会教育是延伸和补充。三者的有机配合才能形成教育合力，避免教育影响的相互抵消。这一理念与\"广义教育\"的三种形式完全对应。<br><br><strong>💡 解题思路：</strong>\"三结合\"对应的就是广义教育的\"三家\"——学校、家庭、社会。不包括自我教育和自然形态教育，因为没有\"合力\"配合的意味。\"三结合\"强调的是不同教育主体间的协同。<br><br><strong>🧠 记忆口诀：</strong>\"三结合就是三家合一：学校主导、家庭基础、社会延伸，形成教育合力。\""
