          "answer": "0",
          "analysis": "<strong>🎯 答案解析：</strong>选\"正确(√)\"。家庭教育是学校教育的基础和补充，具有不可替代的教育作用。<br><br><strong>📚 知识点讲解：</strong>家庭教育是不可替代的教育形式，原因在于：(1)先入性——家庭是儿童最早接触的教育环境，家庭影响具有奠基作用；(2)情感性——亲子关系赋予家庭教育以独特的情感纽带，是学校教育无法复制的；(3)生活性——家庭教育融于日常生活，潜移默化而影响深远；(4)长久性——家庭教育贯穿人的一生。因此，家庭教育是学校教育的基础（奠定早期经验）和补充（弥补学校教育的不足），二者相辅相成但不可互相替代。<br><br><strong>💡 解题思路：</strong>家庭教育的情感纽带和生活渗透性是其不可替代的根本原因。学校可以传授知识，但无法完全替代父母的情感影响和家庭生活的熏陶。<br><br><strong>🧠 记忆口诀：</strong>\"家庭教育不可替，先入为主情感深。生活渗透伴终身，学校家庭互补益。\""
