          "answer": "1",
          "analysis": "<strong>🎯 答案解析：</strong>选\"错误(×)\"。教育促进社会发展的功能是教育的派生功能（社会功能）；教育的本体功能是促进个体发展的功能。<br><br><strong>📚 知识点讲解：</strong>教育功能的层次关系：(1)本体功能（基本功能/个体功能）——促进个体的身心发展，这是教育最直接、最基础的功能；(2)派生功能（社会功能）——通过培养人来促进社会发展(政治、经济、文化等)，这是教育间接的、延伸的功能。社会功能必须通过个体功能的实现才能达成——没有个体的发展，就没有社会的发展。因此社会功能不是\"直接\"的而是\"间接(通过人)\"的。题干把社会功能错误地说成本体功能。<br><br><strong>💡 解题思路：</strong>本体=根基=育人。派生=延伸=对社会。育人(个体)是本，社会功能是由育人派生出来的。记住\"本体育人，派生社会\"。<br><br><strong>🧠 记忆口诀：</strong>\"本体功能是育人，派生功能对社会。个体发展是根基，社会发展由人推。个体在前社会后。\""
