          "analysis": "<strong>🎯 答案解析：</strong>选\"资本主义社会（近代工业革命后）\"。教育与生产劳动的关系从分离走向结合开始于资本主义社会——大工业生产要求工人掌握一定的科学知识。<br><br><strong>📚 知识点讲解：</strong>近代工业革命(18世纪后期开始)是教育与生产劳动关系从分离走向结合的转折点。原因：(1)机器大生产要求劳动者具备读写计算能力和初步科学知识——文盲无法操作机器；(2)科学技术在生产中的应用使教育内容必须包含自然科学；(3)资本主义各国开始推行义务教育，培养合格的劳动力。标志性事件包括英国工厂法中的教育条款、各国义务教育法的颁布等。此后，教育与生产劳动结合成为现代教育的普遍特征。<br><br><strong>💡 解题思路：</strong>\"从分离走向结合\"是近代的事。大工业要求劳动者有文化，于是义务教育兴起，自然科学进课堂。转折点在资本主义/工业革命。<br><br><strong>🧠 记忆口诀：</strong>\"工业革命转折点：机器要大老粗不行，有文化的工人才行。义务教育随工业起，结合由此开新篇。\""
