          "answer": "1",
          "analysis": "<strong>🎯 答案解析：</strong>排除不正确的表述。\"六艺\"中礼乐是核心，射御属军事，书数属基础。需找出违背六艺基本常识的说法。常见错误表述：六艺全是大学内容（实际书、数为\"小艺\"，在小学学习）。<br><br><strong>📚 知识点讲解：</strong>六艺教育：(1)礼——礼仪规范(政治伦理教育)；(2)乐——音乐舞蹈(艺术教育)；(3)射——射箭(军事体育)；(4)御——驾车(军事技术)；(5)书——识字写字(文化基础)；(6)数——计算(数学基础)。其中\"礼\"\"乐\"是核心，重在陶冶情操和规范行为；\"书\"\"数\"是基础(小艺)，安排在小学学习；\"射\"\"御\"是军事技能(大艺)。文(礼乐书数)武(射御)兼备、知(书数)行(礼射御)合一。<br><br><strong>💡 解题思路：</strong>辨析六艺中\"小艺\"(书数→小学)和\"大艺\"(礼乐射御→大学)的区别。不能说六艺全部在大学学习。<br><br><strong>🧠 记忆口诀：</strong>\"六艺分大小：书数小艺学小学，礼乐射御大艺学大学。文武兼备知行合，礼乐是核心。\""
