          "analysis": "<strong>🎯 答案解析：</strong>选\"四书五经\"或\"宋代以后（朱熹）\"。四书之名始于宋朝——朱熹将《大学》《中庸》《论语》《孟子》合称四书并为之作注；五经之名始于汉武帝——设五经博士。<br><br><strong>📚 知识点讲解：</strong>\"四书\"与\"五经\"的来源：(1)五经——《诗经》《尚书》《礼记》《周易》《春秋》，汉武帝时设立五经博士，正式将五经确立为官学教材；(2)四书——《大学》《中庸》《论语》《孟子》，朱熹将这四部书编在一起并作《四书章句集注》，元明清三代科举以此为标准。四书是进入五经的\"阶梯\"——先读四书打基础，再深入研习五经。四书侧重修身齐家，五经侧重治国平天下。<br><br><strong>💡 解题思路：</strong>\"四书之名始于宋朝\"=朱熹创四书体系；\"五经之名始于汉武帝\"=汉武帝立五经博士。两个起点不同。<br><br><strong>🧠 记忆口诀：</strong>\"四书(宋朱熹)：大学中庸论语孟子；五经(汉武帝)：诗书礼易春秋。四书是阶梯，五经是殿堂。\""
