          "analysis": "<strong>🎯 答案解析：</strong>选\"蔡元培\"。蔡元培被称为\"学界泰斗，人世楷模\"——这是毛泽东为他撰写的挽联中的赞誉。<br><br><strong>📚 知识点讲解：</strong>蔡元培(1868-1940)是中国近代最著名的教育家之一，曾担任民国第一任教育总长、北京大学校长等职。主要贡献：(1)\"五育\"并举的教育方针；(2)\"思想自由、兼容并包\"的北大改革；(3)\"以美育代宗教\"的主张；(4)倡导学术自由和教授治校制度。毛泽东称他\"学界泰斗，人世楷模\"，这是对他教育成就和人格风范的高度评价。蔡元培也是中国现代大学制度的奠基人。<br><br><strong>💡 解题思路：</strong>\"学界泰斗，人世楷模\"→毛泽东对蔡元培的评价。<br><br><strong>🧠 记忆口诀：</strong>\"学界泰斗蔡元培，人世楷模毛泽东赞。五育并举兼北大，思想自由又兼容。\""
