          "answer": "1",
          "analysis": "<strong>🎯 答案解析：</strong>选\"使无业者有业，使有业者乐业\"（或\"大职业教育主义\"）。20世纪20年代后，黄炎培将职业教育概括为\"大职业教育主义\"——职业教育不仅是学校教育，更是社会事业。<br><br><strong>📚 知识点讲解：</strong>黄炎培职业教育思想的发展阶段：(1)早期——注重学校形式的职业教育，\"使无业者有业，使有业者乐业\"是核心宗旨；(2)20世纪20年代后——提出\"大职业教育主义\"，认为职业教育不能仅局限于学校范围，而应该\"一切教育都含职业之意味\"，普通教育也应有职业预备。职业教育社会化、科学化是其两大方针。<br><br><strong>💡 解题思路：</strong>\"20世纪20年代后\"的时间标志→黄炎培在这一时期提出了\"大职业教育主义\"。从学校→社会，从狭窄→宽广。<br><br><strong>🧠 记忆口诀：</strong>\"黄炎培职业教育：早期'有业乐业'，后期'大职业教育'。从学校走向社会。\""
