          "analysis": "<strong>🎯 答案解析：</strong>选正确的选项。陶行知的生活教育理论核心观点：(1)生活即教育——生活本身就是教育的内容和过程；(2)社会即学校——整个社会都是教育的场所；(3)教学做合一——教的方法根据学的方法，学的方法根据做的方法。教育与生活不是\"等同\"而是\"融为一体\"。<br><br><strong>📚 知识点讲解：</strong>陶行知师从杜威，将杜威的\"教育即生活\"\"学校即社会\"翻了个跟头，提出\"生活即教育\"\"社会即学校\"\"教学做合一\"三大主张。(1)生活即教育——有什么样的生活就有什么样的教育，生活是教育的源泉；(2)社会即学校——打破学校的\"围墙\"，将整个社会作为教育的场域；(3)教学做合一——\"做\"是核心，教和学都以\"做\"为基础和归宿。陶行知自称\"行动(行)是老子，知识(知)是儿子，创造是孙子\"。<br><br><strong>💡 解题思路：</strong>陶行知=生活教育=三大命题。注意：杜威是\"教育即生活\"，陶行知是逆向的\"生活即教育\"。辨析两者命题方向的不同。<br><br><strong>🧠 记忆口诀：</strong>\"陶行知三句教：生活即教育(过什么生活受什么教育)，社会即学校(到处是学校)，教学做合一(做是核心)。\""
