          "analysis": "<strong>🎯 答案解析：</strong>选\"小先生制\"。\"小先生制\"是陶行知提倡的教师培养和教学方式——即知即传、会的教不会的，大孩教小孩，学生也可以当\"先生\"。<br><br><strong>📚 知识点讲解：</strong>小先生制是陶行知为解决农村教育师资严重不足而创造的一种教学组织形式。核心做法：(1)教师先教部分学生；(2)学会的学生再去教其他不会的学生；(3)层层传递，\"即知即传人\"。这一模式充分发挥了同伴教育的作用，既解决了师资短缺问题，又培养了学生的责任感和教学能力。小先生制在抗日根据地和新中国成立初期的扫盲运动中得到了广泛应用。<br><br><strong>💡 解题思路：</strong>陶行知+解决师资问题→小先生制(即知即传)。<br><br><strong>🧠 记忆口诀：</strong>\"陶行知小先生制：学了就教人，会的教不会，大孩教小孩。即知即传人人师。\""
