          "analysis": "<strong>🎯 答案解析：</strong>选\"教育的不平等（教育机会不均等）\"。\"寒门再难出贵子\"反映的是：社会阶层固化导致教育机会和资源的不均等分配，贫困家庭子女难以通过教育实现阶层上升。<br><br><strong>📚 知识点讲解：</strong>\"寒门难出贵子\"的社会根源：(1)优质教育资源向富裕阶层和城市集中——学区房、课外辅导、名校资源等使富人子女拥有巨大优势；(2)教育成本上升——贫困家庭难以负担教育投资；(3)早期教育差距——家庭文化资本的差异从幼年就开始拉开差距。这反映了教育公平方面存在的深层问题——虽然形式上教育机会均等，但实质上的教育资源不均导致了新的不公平。<br><br><strong>💡 解题思路：</strong>\"寒门\"=贫困家庭，\"难出贵子\"=难以通过教育实现阶层上升。核心问题是教育资源不均等导致的教育不平等。<br><br><strong>🧠 记忆口诀：</strong>\"寒门难出贵子根在教育不公平：资源分配不均，起点已有差距。\""
