          "analysis": "<strong>🎯 答案解析：</strong>选\"教育与宗教分离（或教育的公共性和平等的教育权利）\"。社会主义教育的一个基本特征是坚持教育为人民服务，教育机会平等，教育与宗教相分离。<br><br><strong>📚 知识点讲解：</strong>社会主义教育的基本特征：(1)教育为人民服务——社会主义教育的根本宗旨；(2)教育的平等性——保障每个公民的受教育权利；(3)教育与宗教分离——教育与宗教各自独立，学校不得进行宗教教育；(4)全面发展的教育——德智体美劳全面培养；(5)教育与生产劳动相结合——培养全面发展的人的根本途径。其中\"教育与宗教分离\"是我国宪法和教育法明确规定的基本原则。<br><br><strong>💡 解题思路：</strong>社会主义教育≠宗教教育。教育世俗化、公共性是社会主义教育的题中应有之义。<br><br><strong>🧠 记忆口诀：</strong>\"社会主义教育四性：人民性(为人民)、平等性(人人平等)、世俗性(脱离宗教)、全面性(全面发展)。\""
