          "answer": "0",
          "analysis": "<strong>🎯 答案解析：</strong>选<b><span style=\"color:#4f6ef7;\">描述教育现象、解释教育现象</span></b>（揭示因果关系）。经验科学的教育学研究任务是对教育现象进行客观描述和因果解释。<br><br>\n<strong>📚 知识点讲解：</strong>西方经验科学传统下的教育学，强调<b>实证研究</b>（观察、实验、统计），追求\"是什么\"和\"为什么\"——即描述现象和揭示因果关系。这与<b>规范教育学</b>（追求\"应该做什么\"）相对。例如：经验科学研究\"班级规模与学生成绩的关系\"（是什么/为什么），规范教育学讨论\"班级规模应该多大\"（应该如何）。<br><br>\n<strong>💡 解题思路：</strong>\"经验科学\"的核心是\"靠事实说话\"——观察和解释事实。排除\"制定教育规范\"（规范教育学的任务）、\"推广教育政策\"（行政任务）。<br><br>\n<strong>🧠 记忆口诀：</strong>\"经验科学讲实证：<b>描述是什么，解释为什么。</b>规范教育学才管应该怎么办。\" "
