          "analysis": "<strong>🎯 答案解析：</strong>选<b><span style=\"color:#4f6ef7;\">\"有教无类\"</span></b>（或\"学而不厌，诲人不倦\"）。\"自行束脩以上，吾未尝无诲焉\"——只要主动带一束干肉（薄礼）来求学，我没有不教的。这体现了孔子<b>广收门徒、有教无类</b>的教育主张。<br><br>\n<strong>📚 知识点讲解：</strong>这句话的<b>历史意义</b>：(1)打破了\"学在官府\"的垄断——西周只有贵族子弟才能入学，孔子开办<b>私学</b>，只要有求学之心，不论出身，都可入学；(2)开创了平民教育的先河——\"自行束脩以上\"的门槛很低（十条干肉），体现了较低的经济门槛；(3)体现了<b>\"有教无类\"</b>的核心精神——教育不分贵贱、贫富、地域。孔子被尊为\"万世师表\"正源于此。<br><br>\n<strong>💡 解题思路：</strong>\"束脩\"=薄礼。\"吾未尝无诲焉\"=没有我不教的。→低门槛、广收徒→有教无类。<br><br>\n<strong>🧠 记忆口诀：</strong>\"<b>十条干肉求师门，孔夫子来者不拒。</b>有教无类开私学，万世师表从此始。\" "
