          "analysis": "<strong>🎯 答案解析：</strong>选<b><span style=\"color:#4f6ef7;\">启发性原则</span></b>。苏格拉底产婆术的实质是通过追问和引导，让学生自己发现真理——这正是启发式教学原则的体现。<br><br>\n<strong>📚 知识点讲解：</strong>产婆术与注入式的本质对立：(1)<b>注入式</b>——教师直接把知识灌输给学生，学生被动接受；(2)<b>产婆术（启发式）</b>——教师通过提问激发学生思考，学生主动探索和发现。产婆术之所以叫助产，就在于教师不是把真理这个孩子塞进学生脑子，而是<b>帮助学生自己的思想产出真理的孩子</b>。所以它的实质就是启发，不愤不启不悱不发。<br><br>\n<strong>💡 解题思路：</strong>产婆术的本质=不直接教而是引导=启发。排除注入式、直观性等。<br><br>\n<strong>🧠 记忆口诀：</strong><b>产婆术本质是启发</b>：不灌输，不填鸭，提问引导自通达。教师是助产不是灌。"
